_CAP_HIT_FIXTURE_B64 = ""

_CAP_HIT_FIXTURE = json.loads(
    gzip.decompress(base64.b64decode(_CAP_HIT_FIXTURE_B64)).decode("utf-8")
)
CAP_HIT_RECORDS = {row["bundle_id"]: row for row in _CAP_HIT_FIXTURE["records"]}

# The lead-verified audit table (docs/reviews/2026-07-19-measurement-
# soundness-audit.md P0.4). Values are asserted against the embedded records.
AUDIT_CAP_HIT_TABLE = {
    "p2015-df-cmp-abba-su-b01-b1": (306.6823592185974, 0.09184273619271986, 0.07697866908265495),
    "p2015-df-ph-short-prefill-abs-r04": (300.06907892227173, 0.08203123624288897, 0.07510403184326292),
    "p2015-df-rq-long-prompt-abs-r03": (306.8624310493469, 0.12388120660306769, 0.07972459820477226),
    "p2015-df-cmp-abba-ph-prefill-b03-b1": (300.7070677280426, 0.08090751514250405, 0.07222589642845832),
}


def install_real_cap_hit_manifest(
    runs_root: Path, bundle_id: str, *, tamper: bool = False
) -> None:
    """Write the real campaign manifest + raw trace bytes for one cap-hit."""

    record = CAP_HIT_RECORDS[bundle_id]
    campaign_dir = runs_root / "campaign_manifests"
    raw_dir = campaign_dir / "raw"
    raw_dir.mkdir(parents=True, exist_ok=True)
    raw_bytes = base64.b64decode(record["raw_b64"])
    if tamper:
        raw_bytes += b'{"tampered":true}\n'
    (raw_dir / record["raw_name"]).write_bytes(raw_bytes)
    manifest = {
        "schema_version": "joulewise.campaign_provenance.v1",
        "session_id": record["session_id"],
        "analysis_manifest_id": None,
        "first_physical_run_id": record["first_physical_run_id"],
        "members": [
            {
                "run_id": bundle_id,
                "bundle_ids": [bundle_id],
                "execution": "invoked",
                "preceding_campaign_cooldown": record["cooldown"],
            }
        ],
        "cooldown_gates": [],
    }
    (campaign_dir / f"{record['session_id']}.json").write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def install_synthetic_recovered_manifest(
    runs_root: Path, bundle_ids: list[str], session_id: str = "synthetic-session"
) -> None:
    campaign_dir = runs_root / "campaign_manifests"
    raw_dir = campaign_dir / "raw"
    raw_dir.mkdir(parents=True, exist_ok=True)
    members = []
    for index, bundle_id in enumerate(bundle_ids):
        trace = (
            json.dumps({"rolling_mean_power_w": 0.05, "timestamp_s": float(index)})
            + "\n"
        ).encode("utf-8")
        raw_name = f"{session_id}__cooldown_before_{bundle_id}.jsonl"
        (raw_dir / raw_name).write_bytes(trace)
        cooldown = (
            {
                "result": "first_run_exempt",
                "session_id": session_id,
                "following_run_id": bundle_id,
            }
            if index == 0
            else {
                "result": "recovered",
                "session_id": session_id,
                "following_run_id": bundle_id,
                "raw_artifact": {
                    "path": f"raw/{raw_name}",
                    "sha256": hashlib.sha256(trace).hexdigest(),
                    "records": 1,
                },
            }
        )
        members.append(
            {
                "run_id": bundle_id,
                "bundle_ids": [bundle_id],
                "execution": "invoked",
                "preceding_campaign_cooldown": cooldown,
            }
        )
    (campaign_dir / f"{session_id}.json").write_text(
        json.dumps(
            {
                "schema_version": "joulewise.campaign_provenance.v1",
                "session_id": session_id,
                "analysis_manifest_id": None,
                "first_physical_run_id": bundle_ids[0],
                "members": members,
                "cooldown_gates": [],
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def make_summary(
    value: float,
    *,
    metric: str = "gross_energy_j",
    reducer: str = "0.5.1",
    anchor_bound: float | None = 0.01,
    envelope_point: float | None = None,
    interpolation_bound: float = 0.0,
    precheck_eligible: bool = True,
    precheck_reasons: list[str] | None = None,
    idle_method: str = "duration_weighted_newey_west_bartlett_10s_iid_floor_v2",
) -> dict:
    """Minimal claim-shaped summary for extraction gates (synthetic inputs)."""

    is_phase = metric.startswith("phase_energy_j.")
    point = value if envelope_point is None else envelope_point
    summary: dict = {
        "status": "succeeded",
        "summary_provenance": {"reducer_version": reducer},
        "measurement_quality": {
            "cooldown_cap_hit": None,
            "idle_window_suspect": False,
        },
        LEGACY_THROUGHPUT_FIELD: 225.0,
        READER_THROUGHPUT_FIELD: 223.5,
        "energy_bound_terms_j": {
            "E_interpolation_joint_edge_bound_j": interpolation_bound,
            "E_drift_bound_j": 0.0,
        },
        "idle_mean_uncertainty": {
            "status": "estimated",
            "method": idle_method,
            "correlation_scope": "independent_run",
        },
        "energy_variance_terms_j2": {"E_idle_mean_j2": 1e-4},
    }
    precheck_row: dict = {
        "eligible": precheck_eligible,
        "reasons": list(precheck_reasons or []),
    }
    if is_phase:
        phase = metric.split(".", 1)[1]
        summary["phase_energy_j"] = {phase: value}
        summary["window_evidence_precheck"] = {
            "phase": {
                phase: {
                    **precheck_row,
                    "windows": [
                        {"interpolation_joint_edge_bound_j": interpolation_bound}
                    ],
                }
            }
        }
    else:
        summary[metric if metric != "idle_subtracted_energy_j" else "energy_request_j"] = value
        summary["window_evidence_precheck"] = {
            "gross_request": dict(precheck_row),
            "idle_subtracted_request": dict(precheck_row),
        }
        summary["gross_energy_j"] = summary.get("gross_energy_j", value)
        summary["energy_request_j"] = summary.get("energy_request_j", value)
    if anchor_bound is not None:
        pointer = (
            "/phase_energy_j/" + metric.split(".", 1)[1]
            if is_phase
            else "/" + ("energy_request_j" if metric == "idle_subtracted_energy_j" else metric)
        )
        summary["energy_anchor_shift_envelopes"] = {
            pointer: {
                "method": "common_trace_shift_interval_overlap_v1",
                "anchor_bound_s": 0.05,
                "point_j": point,
                "lower_j": point - anchor_bound,
                "upper_j": point + anchor_bound,
                "max_abs_delta_j": anchor_bound,
            }
        }
        if not is_phase:
            summary["energy_bound_terms_j"]["E_clock_anchor_shift_bound_j"] = (
                anchor_bound
            )
    return summary


def write_bundle(runs_root: Path, bundle_id: str, summary: dict) -> None:
    bundle = runs_root / bundle_id
    bundle.mkdir(parents=True, exist_ok=True)
    (bundle / "summary_metrics.json").write_text(
        json.dumps(summary, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


class RealCapHitJoinTests(unittest.TestCase):
    def test_embedded_fixtures_are_the_four_audited_records(self) -> None:
        self.assertEqual(set(CAP_HIT_RECORDS), set(AUDIT_CAP_HIT_TABLE))
        for bundle_id, (waited, decision, upper) in AUDIT_CAP_HIT_TABLE.items():
            record = CAP_HIT_RECORDS[bundle_id]
            cooldown = record["cooldown"]
            self.assertEqual(cooldown["result"], "cap_hit")
            self.assertEqual(cooldown["waited_s"], waited)
            self.assertEqual(cooldown["decision_rolling_mean_power_w"], decision)
            self.assertEqual(cooldown["effective_upper_w"], upper)
            raw_bytes = base64.b64decode(record["raw_b64"])
            self.assertEqual(
                hashlib.sha256(raw_bytes).hexdigest(),
                cooldown["raw_artifact"]["sha256"],
                f"embedded raw trace for {bundle_id} is not the sealed artifact",
            )

    def test_all_four_real_records_join_as_verified_cap_hits(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            for bundle_id in AUDIT_CAP_HIT_TABLE:
                install_real_cap_hit_manifest(runs_root, bundle_id)
            joined = campaign_cooldown_evidence(runs_root)
            for bundle_id in AUDIT_CAP_HIT_TABLE:
                row = joined[bundle_id]
                self.assertEqual(row["result"], "cap_hit")
                self.assertTrue(row["verified"])

    def test_tampered_raw_trace_never_verifies(self) -> None:
        bundle_id = "p2015-df-rq-long-prompt-abs-r03"
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            install_real_cap_hit_manifest(runs_root, bundle_id, tamper=True)
            joined = campaign_cooldown_evidence(runs_root)
            self.assertFalse(joined[bundle_id]["verified"])

    def test_ambiguous_duplicate_records_never_verify(self) -> None:
        bundle_id = "p2015-df-ph-short-prefill-abs-r04"
        record = CAP_HIT_RECORDS[bundle_id]
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            install_real_cap_hit_manifest(runs_root, bundle_id)
            # A second manifest claims the same bundle recovered cleanly.
            conflicting = {
                "schema_version": "joulewise.campaign_provenance.v1",
                "session_id": record["session_id"],
                "analysis_manifest_id": None,
                "first_physical_run_id": bundle_id,
                "members": [
                    {
                        "run_id": bundle_id,
                        "bundle_ids": [bundle_id],
                        "execution": "invoked",
                        "preceding_campaign_cooldown": {
                            "result": "first_run_exempt",
                            "session_id": record["session_id"],
                            "following_run_id": bundle_id,
                        },
                    }
                ],
                "cooldown_gates": [],
            }
            (runs_root / "campaign_manifests" / "conflict.json").write_text(
                json.dumps(conflicting, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
            joined = campaign_cooldown_evidence(runs_root)
            self.assertFalse(joined[bundle_id]["verified"])
            self.assertEqual(joined[bundle_id]["result"], "unknown")


class AbsoluteCellExtractionTests(unittest.TestCase):
    def _build_corpus(self, tmp: str) -> tuple[Path, list[dict]]:
        runs_root = Path(tmp)
        cap_hit_id = "p2015-df-rq-long-prompt-abs-r03"
        install_real_cap_hit_manifest(runs_root, cap_hit_id)
        clean_ids = [f"clean-r{index:02d}" for index in range(1, 6)]
        install_synthetic_recovered_manifest(runs_root, clean_ids)
        values = [40.1, 39.9, 40.3, 40.0, 39.7]
        for bundle_id, value in zip(clean_ids, values):
            write_bundle(runs_root, bundle_id, make_summary(value))
        write_bundle(runs_root, cap_hit_id, make_summary(41.5))
        members = [{"slot": f"slot-{index}", "bundle_id": bundle_id} for index, bundle_id in enumerate(clean_ids)]
        members.append({"slot": "slot-cap", "bundle_id": cap_hit_id})
        return runs_root, members

    def test_cap_hit_member_is_slot_excluded_and_guard_runs_at_n_minus_1(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root, members = self._build_corpus(tmp)
            report = extract_absolute_cell(
                cell_id="DF-RQ-GROSS-LONG-PROMPT",
                metric="gross_energy_j",
                window_class="request",
                members=members,
                runs_root=runs_root,
                cooldowns=campaign_cooldown_evidence(runs_root),
            )
        self.assertTrue(report.extractable)
        self.assertEqual(report.n_planned, 6)
        self.assertEqual(report.n_admitted, 5)
        self.assertEqual(report.excluded_slots, ("slot-cap",))
        excluded = [member for member in report.members if member.excluded]
        self.assertEqual(len(excluded), 1)
        self.assertTrue(excluded[0].cap_hit)
        self.assertTrue(excluded[0].cooldown_verified)
        assert report.floor is not None
        self.assertEqual(report.floor.n, 5)
        # Same-slot exclusion left n=5: the frozen small-sample guard applies.
        self.assertEqual(report.floor.guard_factor, small_sample_guard_factor(5))
        self.assertAlmostEqual(
            report.floor.guarded_floor_j,
            small_sample_guard_factor(5) * report.floor.unguarded_floor_j,
        )
        self.assertEqual(report.anchor_shift_bound_max_j, 0.01)

    def test_missing_campaign_evidence_fails_the_whole_cell(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root, members = self._build_corpus(tmp)
            orphan = "clean-r99"
            write_bundle(runs_root, orphan, make_summary(40.2))
            members.append({"slot": "slot-orphan", "bundle_id": orphan})
            report = extract_absolute_cell(
                cell_id="DF-RQ-GROSS-LONG-PROMPT",
                metric="gross_energy_j",
                window_class="request",
                members=members,
                runs_root=runs_root,
                cooldowns=campaign_cooldown_evidence(runs_root),
            )
        self.assertFalse(report.extractable)
        self.assertIn("campaign_cooldown_evidence_missing", report.refusal_reasons)
        self.assertIsNone(report.floor)

    def test_tampered_cap_hit_evidence_refuses_instead_of_excluding(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            cap_hit_id = "p2015-df-rq-long-prompt-abs-r03"
            install_real_cap_hit_manifest(runs_root, cap_hit_id, tamper=True)
            clean_ids = [f"clean-r{index:02d}" for index in range(1, 4)]
            install_synthetic_recovered_manifest(runs_root, clean_ids)
            for bundle_id in clean_ids:
                write_bundle(runs_root, bundle_id, make_summary(40.0))
            write_bundle(runs_root, cap_hit_id, make_summary(41.5))
            members = [
                {"slot": bundle_id, "bundle_id": bundle_id}
                for bundle_id in (*clean_ids, cap_hit_id)
            ]
            report = extract_absolute_cell(
                cell_id="DF-RQ-GROSS-LONG-PROMPT",
                metric="gross_energy_j",
                window_class="request",
                members=members,
                runs_root=runs_root,
                cooldowns=campaign_cooldown_evidence(runs_root),
            )
        self.assertFalse(report.extractable)
        self.assertIn("campaign_cooldown_evidence_missing", report.refusal_reasons)
        self.assertEqual(report.excluded_slots, ())

    def test_precheck_failure_is_a_hard_gate_source_clean_never_overrides(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root, members = self._build_corpus(tmp)
            failing = make_summary(40.2, precheck_eligible=False, precheck_reasons=["clock_anchor_unresolved"])
            # Source-clean provenance must NOT rescue a failed metric
            # precheck (audit P0.2 regression).
            failing["metadata_note_source_provenance_claim_eligible"] = True
            write_bundle(runs_root, "clean-r01", failing)
            report = extract_absolute_cell(
                cell_id="DF-RQ-GROSS-LONG-PROMPT",
                metric="gross_energy_j",
                window_class="request",
                members=members,
                runs_root=runs_root,
                cooldowns=campaign_cooldown_evidence(runs_root),
            )
        self.assertFalse(report.extractable)
        self.assertIn("clock_anchor_unresolved", report.refusal_reasons)

