    def test_unknown_reducer_wire_refuses(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root, members = self._build_corpus(tmp)
            write_bundle(runs_root, "clean-r05", make_summary(39.7, reducer="0.7.0"))
