    def test_idle_subtracted_cell_requires_the_exact_idle_method_pair(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            runs_root = Path(tmp)
            clean_ids = ["idle-r01", "idle-r02", "idle-r03"]
